package com.aditya.day13.payment; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/payments") public class PaymentController{final PaymentRepo r;PaymentController(PaymentRepo r){this.r=r;}record Req(UUID orderId,double amount,String idempotencyKey){}@PostMapping public Payment pay(@RequestBody Req x){return r.findByIdempotencyKey(x.idempotencyKey()).orElseGet(()->{Payment p=new Payment();p.setOrderId(x.orderId());p.setAmount(x.amount());p.setIdempotencyKey(x.idempotencyKey());p.setStatus("SUCCESS");return r.save(p);});}@GetMapping("/{orderId}")public List<Payment> get(@PathVariable UUID orderId){return r.findByOrderId(orderId);}@PostMapping("/{orderId}/refund")public Payment refund(@PathVariable UUID orderId){Payment p=r.findByOrderId(orderId).stream().findFirst().orElseThrow();p.setStatus("REFUNDED");return r.save(p);}}